"use strict";(self.webpackChunkmy_blog=self.webpackChunkmy_blog||[]).push([[981],{7233:e=>{e.exports=JSON.parse('{"permalink":"/my-blog/unresponsive-sme","source":"@site/blog/2025-04-30-unresponsive-sme.md","title":"How to Deal With an Unresponsive SME","description":"Communication plays a vital role in many of today\u2019s professions. The ability to gather and share information is essential and forms the basis for completing projects or achieving predefined goals. One of these professions that involves building and presenting knowledge is technical writing.","date":"2025-04-30T00:00:00.000Z","tags":[{"inline":true,"label":"Technical Writing","permalink":"/my-blog/tags/technical-writing"},{"inline":true,"label":"SME","permalink":"/my-blog/tags/sme"}],"readingTime":4.13,"hasTruncateMarker":false,"authors":[{"name":"Piotr Kalarus","title":"Technical Writer, Translator","url":"https://www.linkedin.com/in/kalarp/","page":{"permalink":"/my-blog/authors/kalarp"},"socials":{"linkedin":"https://www.linkedin.com/in/kalarp/","github":"https://github.com/kalarp"},"imageURL":"https://kalarp.github.io/images/photo.jpg","key":"kalarp"}],"frontMatter":{"slug":"unresponsive-sme","title":"How to Deal With an Unresponsive SME","authors":["kalarp"],"tags":["Technical Writing","SME"]},"unlisted":false,"prevItem":{"title":"A \u201890s Gamer\u2019s Journey into the Forgotten World of Adventure Games","permalink":"/my-blog/90s-gamer-series"}}')},8453:(e,t,n)=>{n.d(t,{R:()=>a,x:()=>r});var o=n(6540);const i={},s=o.createContext(i);function a(e){const t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),o.createElement(s.Provider,{value:t},e.children)}},9288:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>u,frontMatter:()=>a,metadata:()=>o,toc:()=>h});var o=n(7233),i=n(4848),s=n(8453);const a={slug:"unresponsive-sme",title:"How to Deal With an Unresponsive SME",authors:["kalarp"],tags:["Technical Writing","SME"]},r=void 0,l={authorsImageUrls:[void 0]},h=[{value:"The Colour of Personality",id:"the-colour-of-personality",level:2},{value:"More Useful Tips",id:"more-useful-tips",level:2},{value:"Conclusion",id:"conclusion",level:2}];function c(e){const t={em:"em",h2:"h2",li:"li",p:"p",ul:"ul",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.p,{children:"Communication plays a vital role in many of today\u2019s professions. The ability to gather and share information is essential and forms the basis for completing projects or achieving predefined goals. One of these professions that involves building and presenting knowledge is technical writing."}),"\n",(0,i.jsx)(t.p,{children:"The role of a technical writer is to communicate complex concepts to technical and non-technical audiences. Think of it as solving a Rubik\u2019s cube, where the unsolved cube represents a set of information you have gathered from subject matter experts (SMEs). Your job is to organise and design the information so that, like a solved Rubik\u2019s cube, it makes sense to the end user. Everything is in its logical place. To do this, you need to work productively with members of different teams inside and outside the organisation. But not everyone is easy to work with. And when you encounter an unresponsive SME, you may quickly realise that your writing project is at risk. If you ever find yourself in this situation, you can think of several ways to move your work forward. However, there is one method that can be particularly useful when dealing with colleagues and business partners: personality types based on the DISC model."}),"\n",(0,i.jsx)(t.h2,{id:"the-colour-of-personality",children:"The Colour of Personality"}),"\n",(0,i.jsxs)(t.p,{children:["In his book ",(0,i.jsx)(t.em,{children:"Surrounded by Idiots"}),", Thomas Erikson states that personality colour differences are responsible for most misunderstandings and conflicts. Knowing your and your colleagues\u2019 personality types can help you communicate and work successfully. There are four personality colours:"]}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"Red \u2014 fast thinking, fast acting, determined extroverts with strong leadership qualities. They are very pragmatic and want to see immediate benefits or results. They may ignore your approaches if they don\u2019t see the reason or if you don\u2019t get to the point early enough. So be specific."}),"\n",(0,i.jsx)(t.li,{children:"Yellow \u2014 extroverts who focus on social aspects; they are very talkative, enthusiastic, and outgoing. They may not be unresponsive, but obtaining detailed information from them can still be challenging. Their high energy and tendency to drift off into non-business topics can be challenging. With this in mind, try to moderate the discussion to get all the answers you need."}),"\n",(0,i.jsx)(t.li,{children:"Green \u2014 introverts and good listeners. They manage their time well and don\u2019t like abrupt action. Green personalities carry out their tasks step by step once they have understood every aspect of the project. Introducing a sense of urgency when communicating with green types can help move things forward."}),"\n",(0,i.jsx)(t.li,{children:"Blue \u2014 detail-oriented perfectionists. Remember that they have high expectations and not just of themselves. They communicate in a concrete and data-driven way, but they also overthink and tend to make things personal. Always prepare thoroughly for meetings with blue types; write down your questions in advance."}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"Try to identify the personality types of SMEs. Of course, you can\u2019t send everyone a personality test before you approach them. Make the most of the first contact. Get to know your colleagues. Make small talk. Ask about their interests, hobbies and opinions. You can gain valuable insights by observing their behaviour, body language and communication style. The next step is to adapt accordingly."}),"\n",(0,i.jsx)(t.h2,{id:"more-useful-tips",children:"More Useful Tips"}),"\n",(0,i.jsx)(t.p,{children:"In a fast-paced business environment or a distributed team, you may not have the time or opportunity to get to know someone well early on. Often, your first approach will be strictly project-related. But that doesn\u2019t mean there aren\u2019t other ways to get answers effectively:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"Identify the SME\u2019s preferred means of contact \u2014 some colleagues may take a long time to respond to an email. They may be too busy or favour discussing things in person. Ask your SMEs how they would like to be contacted and stick to that. You can also ask your colleagues who have worked with SMEs about the best way to contact them."}),"\n",(0,i.jsx)(t.li,{children:"Use the calendar \u2014 don\u2019t catch your colleagues off guard and approach them unexpectedly. Plan and arrange meetings well in advance. Send a brief agenda with the invitation. Allow SMEs to prepare for the meeting as well as you do."}),"\n",(0,i.jsx)(t.li,{children:"Get involved \u2014 be proactive. Attend product meetings, even if they are not strictly related to the documentation process. Find out as much as you can about the product before you meet the SMEs. Ask them to verify what you\u2019ve already learned. And remember to use open-ended questions."}),"\n",(0,i.jsx)(t.li,{children:"Get others involved \u2014 add colleagues working on the project to an email or invite them to a meeting. This can work wonders with some SMEs who need a bit of pressure. The aim is not to involve managers, but to demonstrate that a group is ready to progress."}),"\n"]}),"\n",(0,i.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,i.jsx)(t.p,{children:"As a technical writer, you can\u2019t just focus on your writing craft. You also need to develop your interpersonal and interviewing skills. Mastering these will help you navigate professional relationships for better collaboration and results. Remember that every SME has different motivations, expectations and preferred ways of doing things. Your challenge is to find the right approach to unlock the resources you need for your documentation."})]})}function u(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}}}]);